  keysT:"Las claves de Aisha",k:{sis:"SIS · S-20417",p88:"LP · P-88",mail:"SC · su correo",p91:"LP · P-91"},mailRaw:"Correo tal cual: ␣Aisha.Khan@Mail.example␣",mailN:"En staging: aisha.khan@mail.example",
  ruleT:"Reglas, la más confiable primero",rules:["1. Un ID de estudiante es uno","2. Una cuenta es el ID que guarda","3. Un correo, si lo tiene uno solo","4. Lo demás: estudiante propio"],
